import { useState } from 'react'
import { useNavigate } from 'react-router-dom'

import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  type SelectChangeEvent,
  Typography,
  Checkbox,
  FormControlLabel
} from '@mui/material'

import { MEMBER_VALUES } from 'src/data/MemberValues'
import type { MemberLevel } from 'src/models/clubMember'

import { useRequestClubMember } from 'src/hooks/api/memberRequest'
import useSafeAuthUser from 'src/hooks/useSafeAuthUser'

interface MemberRequestDialogProps {
  isOpen: boolean
  clubId: number
  clubName: string
  onClose: () => void
}

const MemberRequestDialog: React.FC<MemberRequestDialogProps> = ({ isOpen, clubId, clubName, onClose }) => {
  const navigate = useNavigate()
  const { isLoggedIn, userInfo } = useSafeAuthUser()
  const requestClubMemberMutation = useRequestClubMember()

  const [requestedLevel, setRequestedLevel] = useState<MemberLevel>('정회원')
  const [isContactProvided, setIsContactProvided] = useState<boolean>(false)

  const handleLevelSelectChange = (event: SelectChangeEvent<string>) => {
    setRequestedLevel(event.target.value as MemberLevel)
  }

  const handleContactProvidedChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setIsContactProvided(event.target.checked)
  }

  const handleSubmitButtonClick = () => {
    requestClubMemberMutation.mutate(
      {
        clubId,
        data: { memberLevel: requestedLevel }
      },
      {
        onSettled: () => {
          onClose()
        }
      }
    )
  }

  const handleLoginButtonClick = () => {
    onClose()
    navigate('/auth/login')
  }

  return (
    <Dialog open={isOpen} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogContent sx={{ pt: 3 }}>
        {!isLoggedIn ? (
          <Box textAlign="center">
            <Typography variant="h4" color="primary">
              로그인 후 동아리 회원 인증을 신청할 수 있습니다.
            </Typography>
            <Typography sx={{ mt: 1.5 }} color="text.secondary">
              회원 인증을 신청하면 동아리 운영진에게 알림 메일이 전송됩니다.
              <br />
              동아리 운영진이 회원 인증을 수락하면 동아리 후기를 작성하고,
              <br />
              동아리 회원 전용 쿠폰 혜택을 받을 수 있어요.
            </Typography>
          </Box>
        ) : (
          <Box>
            <Typography variant="h4" color="primary" textAlign="center">
              기존 회원 인증 신청
            </Typography>
            <Typography sx={{ mt: 2 }}>
              {userInfo?.name} ({userInfo?.studentId}) 계정으로 {clubName}에 회원 인증을 신청합니다.
            </Typography>
            <FormControl fullWidth sx={{ mt: 2.5 }}>
              <InputLabel id="member-request-level-label">신청할 회원 등급</InputLabel>
              <Select
                labelId="member-request-level-label"
                value={requestedLevel}
                label="신청할 회원 등급"
                onChange={handleLevelSelectChange}
              >
                {MEMBER_VALUES.level.map(({ value, display }) => (
                  <MenuItem key={value} value={value}>
                    {display}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
            <Typography sx={{ mt: 2 }} color="text.secondary">
              회원 인증을 신청하면 동아리 운영진에게 알림 메일이 전송됩니다.
              <br />
              동아리 운영진이 회원 인증을 수락하면 동아리 후기를 작성하고,
              <br />
              동아리 회원 전용 쿠폰 혜택을 받을 수 있어요.
            </Typography>
          </Box>
        )}
      </DialogContent>
      {isLoggedIn && (
        <Box sx={{ px: 3, pb: 1, display: 'flex', justifyContent: 'center' }}>
          <FormControlLabel
            control={<Checkbox checked={isContactProvided} onChange={handleContactProvidedChange} />}
            label="동아리 운영진에게 내 정보에 등록된 전화번호와 이메일을 제출합니다"
          />
        </Box>
      )}
      <DialogActions sx={{ px: 3, pb: 3, justifyContent: 'center', gap: 1 }}>
        <Button variant="outlined" onClick={onClose}>
          취소
        </Button>
        {!isLoggedIn ? (
          <Button variant="contained" onClick={handleLoginButtonClick}>
            로그인
          </Button>
        ) : (
          <Button variant="contained" onClick={handleSubmitButtonClick} disabled={!isContactProvided}>
            신청하기
          </Button>
        )}
      </DialogActions>
    </Dialog>
  )
}

export default MemberRequestDialog
